QUESTION_KINDS = [
    ("identity","evidence","validation"), ("definition","authority","interoperability"),
    ("relationship","temporal","access"), ("requirement","decision","exception"),
    ("ownership","provenance","privacy"), ("classification","quality","security"),
    ("composition","measurement","validation"), ("state","lifecycle","retention"),
]

def make_finding(raw, index):
    fid, name, description, refs, value_kind, required = raw
    kinds = QUESTION_KINDS[index % len(QUESTION_KINDS)]
    if index < 4:
        identity_strategy = "Register identifier plus " + fid + " assertion or event identifier; no entry segment is required for register-scoped records."
    else:
        identity_strategy = "Register-qualified entry identifier plus " + fid + " assertion or event identifier; subject name, identifier value, timestamp and digest never identify the entry alone."
    return {
        "id":fid,"name":name,"description":description,"source_refs":refs,
        "questions":[
            {"id":fid+"-q01","text":f"What identifiers, authorities, classes, versions, scope and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers and authorities","classes and profiles","versions and scope","values and explicit unknowns"]},
            {"id":fid+"-q02","text":f"Which source, evidence, event time, effective time and knowledge time support {name.lower()}?","kind":kinds[1],"answer_data":["source and authority","evidence and method","event and effective time","observation and knowledge time","confidence and assumptions"]},
            {"id":fid+"-q03","text":f"How may {name.lower()} be validated, contested, corrected, superseded, retained and disclosed without silent merging or expanding authority?","kind":kinds[2],"answer_data":["validation","contest and redress","successor history","retention and access","authority boundary"]},
        ],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured identity-register data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing registry record for "+name.lower()+" with authority, event and knowledge time, provenance and disclosure marking.","media_or_form":["logical identity-register assertion","source evidence, event or validation reference"],"serial":True,"identity_strategy":identity_strategy,"source_refs":refs}],
        "inline_only_rationale":None,
    }

def structure():
    cursor = 0
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        made_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made = []
            for raw in findings:
                made.append(make_finding(raw, cursor)); cursor += 1
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":made})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

